class AirScale(UnixFunctionality):
    """
    Class with robot keywords for the Air Scale GNB device.
    """
    oam_type = None

    def __init__(self,
                 device_name='GNB0',  # type: 'Optional[str]'
                 device=None,  # type: 'Optional[MolerAirScale]'
                 autoconnect=False,  # type: 'Optional[bool]'
                 get_device=False,  # type: 'Optional[bool]'
                 oam_ip=None,  # type: 'Optional[str]'
                 mrbts_id=None,  # type: 'Optional[str, int]'
                 nrbts_id=None  # type: 'Optional[str, int]'
                 ):

        super(AirScale, self).__init__(device_name=device_name, device=device,
                                       autoconnect=autoconnect, get_device=get_device)

        self.oam_ip = oam_ip
        self.mrbts_id = mrbts_id
        self.nrbts_id = nrbts_id

        if autoconnect:
            self.connect_to_gnb()

    @MolerTest.raise_background_exceptions(check_steps_end=True)
    def connect_to_gnb(self):
        """
        The keyword creates the gNB device object in the FCT state based on the given device name.

        :return: None
        """
        self.connect()
        self.device.goto_state("FCT")

        if AirScale.oam_type is None:
            AirScale.oam_type = self._get_oam_type()

        MolerTest.steps_end()

    @MolerTest.raise_background_exceptions(check_steps_end=True)
    def get_cpri_link_status(self):
        """
        Get status of the CPRI link.

        :return: None
        """
        self.device.goto_state("FSP")
        cmd_devmem = self.device.get_cmd(cmd_name="devmem", cmd_params={"address": "0xdf201004"})
        result = cmd_devmem()
        MolerTest.steps_end()
        return result["VALUE"]

    @MolerTest.raise_background_exceptions()
    def get_asir_container_status(self, name):
        """
        Get status of the ASiR container.

        :param name: container number.
        :return: True if container is up, False otherwise.
        """
        return (self._check_if_asir_container_is_up()
                and self._check_if_all_processes_on_asir_container_are_running()
                and self._check_asir_container_state(name))

    @MolerTest.raise_background_exceptions()
    def get_container_state(self, name):
        """
        Get state of a container.

        :param name: container name
        :return: container state
        """
        self.device.goto_state("FCT")
        cmd_lxc_info = self.device.get_cmd(cmd_name="lxc_info", cmd_params={"name": name,
                                                                            "options": "-s"})
        result = cmd_lxc_info()
        return result["RESULT"]["State"]

    _re_container = re.compile(r'0x\w*19')

    @MolerTest.raise_background_exceptions()
    def _check_if_asir_container_is_up(self):
        """
        Check if the container is up.

        :return: True if container is up, False otherwise.
        """
        self.device.goto_state("FCT")
        cmd_lxcls = self.device.get_cmd(cmd_name="lxc_ls")
        result = cmd_lxcls()
        for element in result["RESULT"]:
            if self.get_asi_container_id() in element:
                return True
        return False

    @MolerTest.raise_background_exceptions()
    def _check_if_all_processes_on_asir_container_are_running(self):
        """
        Check the running processes.

        :return: True if required processes are up, False otherwise.
        """
        self.device.goto_state("LXC")
        cmd_ps = self.device.get_cmd(cmd_name="ps", cmd_params={"options": "-e"})
        ps_result = cmd_ps()
        required_processes = ["DBServerexe", "FaRecoexe", "BCtrlexe", "AsiRp1Agentexe", "ConfigManagemen", "BMgrexe",
                              "StateManagement"]
        running_processes = [d['CMD'] for d in ps_result]
        result = all(element in running_processes for element in required_processes)
        return result

    @MolerTest.raise_background_exceptions()
    def _check_asir_container_state(self, name):
        """
        Check a container state.

        :param name: container name.
        :return: True if status is RUNNING, False otherwise.
        """
        state = self.get_container_state(name)
        if state == "RUNNING":
            return True
        else:
            return False

    @MolerTest.raise_background_exceptions(check_steps_end=True)
    def get_asihub_version_from_targetbd(self):
        """
        Get asihub build version from /rom/TargetBD.*.xml.

        :return: the build version as string.
        """
        regex_helper = RegexHelper()
        self.device.goto_state("FCT")
        grep_cmd = self.device.get_cmd(
            cmd_name="grep",
            cmd_params={'options': 'ASIHUB_5G /ffs/run/TargetBD*.xml'}
        )

        result = grep_cmd()
        build_version = None

        for line in result['LINES']:
            # ASIHUB_5G_19.02.R02
            # ASIHUB_5G_RL19_19.06.R01
            if regex_helper.search(r"(?P<BUILD_VERSION>ASIHUB_5G_\S*\d{2}\.\d{2}\.R\d+)", line):
                build_version = regex_helper.group("BUILD_VERSION")
                break

        MolerTest.steps_end()
        return build_version

    @MolerTest.raise_background_exceptions()
    def get_actasi_status(self, scf_dir="/tmp/", current_scf_name="Current_SCF.xml"):
        """
        Get actAsi parameter value

        :param scf_dir: path to current scf file
        :param current_scf_name: name of current scf file
        :return: None
        """
        Rest(self, oam_ip=self.oam_ip).get_current_commissioning(scf_dir, current_scf_name)

        current_scf_path = os.path.join(scf_dir, current_scf_name)
        with open(current_scf_path, 'r') as current_scf:
            content = current_scf.read()
        #    <p_name="actAsi">true/p>
        if re.findall('actAsi">true', content):
            return True
        else:
            return False

    def set_actasi_to_true(self, scf_dir="/tmp/", current_scf_name="Current_SCF.xml",
                           modify_scf_name="Modify_SCF.xml"):
        """
        Set actasi parameter to True

        :param scf_dir: path to current and modify scf file
        :param current_scf_name: name of current scf file
        :param modify_scf_name: name of modify scf file
        :return: None
        """
        modify_scf_path = self.modify_select_parameters([{'value': "true", 'p_name': "actAsi"}], scf_dir,
                                                        current_scf_name, modify_scf_name)
        Rest(self, oam_ip=self.oam_ip).perform_commissioning(modify_scf_path)

    def set_actasi_to_false(self, scf_dir="/tmp/", current_scf_name="Current_SCF.xml",
                            modify_scf_name="Modify_SCF.xml"):
        """
        Set actasi parameter to False

        :param scf_dir: path to current and modify scf file
        :param current_scf_name: name of current scf file
        :param modify_scf_name: name of modify scf file
        :return: None
        """
        modify_scf_path = self.modify_select_parameters([{'value': "false", 'p_name': "actAsi"}], scf_dir,
                                                        current_scf_name, modify_scf_name)
        Rest(self, oam_ip=self.oam_ip).perform_commissioning(modify_scf_path)

    def modify_select_parameters(self, param=[{'value': '', 'p_name': ''}], scf_dir="/tmp/",
                                 current_scf_name="Current_SCF.xml", modify_scf_name="Modify_SCF.xml"):
        """
        Modify selected parameters values in the given scf file.

        :param param: dictionary with parameters values
        :param scf_dir: path to current and modify scf file
        :param current_scf_name: name of current scf filel
        :param modify_scf_name: name of modify scf file
        :return: path to modified scf.
        """
        Rest(self, oam_ip=self.oam_ip).get_current_commissioning(scf_dir, current_scf_name)

        current_scf_path = os.path.join(scf_dir, current_scf_name)
        modify_scf_path = os.path.join(scf_dir, modify_scf_name)
        commissioning().modify_scf(current_scf_path, modify_scf_path, param)
        return modify_scf_path

    def get_reset_reason(self):
        """
        Get a reason for resetting.

        :return: reset reason as string
        """
        legacy_reset_reason_file = '/sys/devices/platform/reset/rst_stat/reset_reason'
        reset_reason_file = '/dev/ddal/reset/rst_stat/reset_reason'
        self.device.goto_state("FCT")

        if self.check_if_file_exists(file_path=legacy_reset_reason_file):
            reset_reason = self.get_file_content(legacy_reset_reason_file)
        else:
            reset_reason = self.get_file_content(reset_reason_file)

        return reset_reason[0]

    def get_reset_counter(self):
        """
        Get how many times gNB has been reset since last configuration update.

        :return: reset counter as int
        """
        self.device.goto_state("FCT")
        reset_counter_file_content = self.get_file_content('/var/tmp/hwapi/RP_RAM_field_hwapiResetLoopCounter.txt')
        reset_counter_match_obj = re.match(r'0x(?P<NR>\S+) :', reset_counter_file_content[-1])
        reset_counter = reset_counter_match_obj.group("NR")
        if reset_counter == '1' or reset_counter == '0':
            return 1
        else:
            return int(reset_counter, 16)

    def _is_siteoam_in_targetbd(self):
        """
        Check if siteoam component is in TargetBD*.xml file.

        :return: True or False
        """
        self.device.goto_state("FCT")
        check_siteoam = self.device.get_cmd(cmd_name="grep",
                                            cmd_params={"options": "'name=\"siteoam\"' /rom/TargetBD*.xml"})
        result = check_siteoam()
        if "LINES" in result and len(result['LINES']):
            return True
        else:
            return False

    def _is_admincli_in_targetbd(self):
        """
        Check if admin-cli component is in TargetBD*.xml file.

        :return: True or False
        """
        self.device.goto_state("FCT")
        check_admincli = self.device.get_cmd(cmd_name="grep",
                                             cmd_params={"options": "'name=\"admin-cli\"' /rom/TargetBD*.xml"})
        result = check_admincli()
        if "LINES" in result and len(result['LINES']):
            return True
        else:
            return False

    def _get_oam_type(self):
        """
        Get OAM type

        :return: oam_type - MZOAM or COAM
        """
        oam_type = 'COAM'
        if self._is_siteoam_in_targetbd():
            oam_type = 'MZOAM'
        elif self._is_admincli_in_targetbd():
            oam_type = 'COAM'
        return oam_type

    @MolerTest.raise_background_exceptions()
    def collect_trs_logs(self, output_dir):
        """
        collect TRS logs from gNB.

        :param output_dir: directory on local device
        :return: None
        """
        self.device.goto_state("FCT")
        cmd_dbgrrc = self.device.get_cmd(cmd_name="dbgrrc_show",
                                         cmd_params={"options": "port 14 >/tmp/dbgrrc.txt"})
        cmd_dbgrrc()

        util().download_files(local_dir=output_dir, remote_file='dbgrrc.txt',
                              remote_dir='/tmp', remote_device_name=self.name, log_level='info',
                              hops=[self.ws_name], timeout=120)
        util().download_files(local_dir=output_dir, remote_file='trs_tpl_events*.log',
                              remote_dir='/tmp', remote_device_name=self.name,
                              hops=[self.ws_name], timeout=120)
        util().download_files(local_dir=output_dir, remote_file='trs*',
                              remote_dir='/var/log', remote_device_name=self.name,
                              hops=[self.ws_name], timeout=120)
        util().download_files(local_dir=output_dir, remote_file='messages',
                              remote_dir='/var/log', remote_device_name=self.name,
                              hops=[self.ws_name], timeout=120)
        util().download_files(local_dir='{}/rxlos0'.format(output_dir), remote_file='rx_los',
                              remote_dir='/sys/class/sfp/sfp_0_0', remote_device_name=self.name,
                              hops=[self.ws_name], timeout=120)
        util().download_files(local_dir='{}/rxlos1'.format(output_dir), remote_file='rx_los',
                              remote_dir='/sys/class/sfp/sfp_0_1', remote_device_name=self.name,
                              hops=[self.ws_name], timeout=120)

    def check_hw_module_status(self, timeout=30):
        """
        Check current installed hardware module status.

        :param: timeout - wait time to complete command. (unit : second)
        :return: True - all kinds of hw module are all ready
                 False - at least one hw module is not ready
        """
        master_node_id = self._get_master_node_id()
        return self._check_hw_module_status(master_node_id=master_node_id, timeout=timeout)

    # flake8: noqa: C901
    @MolerTest.raise_background_exceptions()
    def get_asi_container_id(self, timeout=300):
        """
        Login GNB and get asi container id

        :param: timeout - wait time to complete command. (unit : second)
        :return: string, asi container id
        """
        timeout = float(timeout)
        start_time = time.time()
        airscale_device = self.device
        while True:
            try:
                airscale_device.goto_state('FCT', rerun=3)
                get_container_id_cmd = airscale_device.get_cmd(
                    cmd_name='ls',
                    cmd_params={'options': '-l /ram | grep "/ram/node_ASI00"'})
                dict_container = get_container_id_cmd()

                container_elem_list = []

                def get_dict_keys(dict_container):
                    for key in dict_container:
                        if type(dict_container[key]).__name__ == 'dict':
                            get_dict_keys(dict_container[key])
                            container_elem_list.append(key)
                        else:
                            container_elem_list.append(key)

                get_dict_keys(dict_container)
                for container_elem in container_elem_list:
                    if 'node' in container_elem:
                        container_id = container_elem.split('_')[-1]
                        break

            except CommandFailure as e:
                MolerTest.error('Cannot get information about container id! {}'.format(e), raise_exception=True)

            if container_id:
                # then update the moler context of airscale
                airscale_device.change_container_id(container_id)
                return container_id
            if time.time() - start_time >= timeout:
                MolerTest.error('Cannot get ASiCtl container id in {}s.'.format(timeout), raise_exception=True)
            time.sleep(2)

    @staticmethod
    def _parse_container_id(running_process):
        """
        Parse and get container id from running process

        :param running_process: string, including all running process in AirScale.
        :return: string, asi container id if found it, else return empty string
        """
        container_id = ''
        for process in running_process:
            m = re.search(r'-n (?P<CONTAINER_ID>\S+) .+ /ffs/run/swpool/ASICNTR', process['CMD'])
            if m:
                container_id = m.group('CONTAINER_ID')
                break
        return container_id

    @MolerTest.raise_background_exceptions()
    def _check_hw_module_status(self, master_node_id='0x1011', timeout=30):
        """
        Check hardware status for controller board and baseband board.

        :param: master_node_id - default '0x1011' means boards are installed in left side of AMIA.
        :param: timeout - wait time to complete command. (unit : second)
        :return: True - all kinds of hw module are all ready
                 False - at least one hw module is not ready
        """
        self.device.goto_state("FCT")
        cmd_export = self.device.get_cmd(cmd_name="export", cmd_params={"set_param": "PYTHONPATH=/opt/hwmt/python"})
        cmd_export()
        cmd_check = self.device.get_cmd(cmd_name="adet", cmd_params={"options": "-s -n {}".format(master_node_id)})
        result = cmd_check(timeout)
        for board_name, board_status in result['BOARD_STATUS'].items():
            if 'ready' not in board_status:
                return False
        return True

    @MolerTest.raise_background_exceptions()
    def _get_master_node_id(self):
        """
        Get master node id (masternid) from output of command 'ps -ef'.
        For example:
        ...
        root      3070  2931  0 09:52 ?        00:00:02 /opt/CCS_RT/CCSRTDaemonExe --startup=nid=0xe00a
        rtconfigfile=/ram/RTCCSConfig.xml testerport=35005 masternid=0x2011 executable=/opt/rthwapi/RT
        HWAPIDaemon --file /ram/RTHWAPIConfig.xml#sys.hwapi.online
        -c app.hwapi.appcfg.filename /ram/AppDefRT.txt ccs.service.aapostmortem.forcelogs 1
        ...

        :return: (str) master node id, else exception will be raised if no available master node id.
        """
        self.device.goto_state("FCT")
        cmd_node = self.device.get_cmd(cmd_name="ps", cmd_params={"options": "-ef"})
        result = cmd_node()
        node_id = None
        for process in result:
            m = re.search(r'/opt/CCS/CCSDaemonExe.+\s+masternid=(?P<NODE_ID>0x\S+)\s+.*', process['CMD'])
            if m:
                node_id = m.group('NODE_ID')
                return node_id
        if not node_id:
            MolerTest.error('No available master node id!')
